// Cross-part checks that don't belong to any single part's own state.rs,
// since they need visibility into more than one part's discriminators at
// once — this is the one place that's true.
//
// To see the printed output:
//   cargo test -p openstake-core --lib tests:: -- --nocapture

use crate::{amm, config, settlement};

// Discriminators are the first eight bytes of an instruction, and the tag
// stored in every account. They're generated by hashing names in
// tools/compute-discriminators, so a collision isn't impossible - just
// unlikely. If two ever matched, the dispatcher in lib.rs would silently route
// a call to the wrong handler, or an account would be read as the wrong type.
//
// Position and Vault used to be in the account list. Both are gone: positions
// are SPL token balances now, and a vault is a plain SPL token account, so
// neither carries a discriminator of ours any more.
#[test]
fn discriminators_are_all_distinct_across_every_part() {
    let account_discs: [(&str, [u8; 8]); 2] = [
        ("Market", amm::state::MARKET_DISCRIMINATOR),
        ("Config", config::state::CONFIG_DISCRIMINATOR),
    ];

    println!("account discriminators:");
    for (name, disc) in account_discs {
        println!("  {name:<8} {disc:?}");
    }

    for i in 0..account_discs.len() {
        for j in (i + 1)..account_discs.len() {
            assert_ne!(
                account_discs[i].1, account_discs[j].1,
                "account discriminators {} and {} collide",
                account_discs[i].0, account_discs[j].0
            );
        }
    }

    // Every instruction the dispatcher matches on belongs in this list. Adding
    // one to lib.rs without adding it here leaves the collision unchecked.
    let ix_discs: [(&str, [u8; 8]); 6] = [
        ("initialize_market", amm::state::INITIALIZE_MARKET),
        ("place_bet", amm::state::PLACE_BET),
        ("settle_market", settlement::state::SETTLE_MARKET),
        ("claim", settlement::state::CLAIM),
        ("initialize_config", config::state::INITIALIZE_CONFIG),
        ("update_config", config::state::UPDATE_CONFIG),
    ];

    println!("instruction discriminators:");
    for (name, disc) in ix_discs {
        println!("  {name:<18} {disc:?}");
    }

    for i in 0..ix_discs.len() {
        for j in (i + 1)..ix_discs.len() {
            assert_ne!(
                ix_discs[i].1, ix_discs[j].1,
                "instruction discriminators {} and {} collide",
                ix_discs[i].0, ix_discs[j].0
            );
        }
    }

    println!(
        "all {} discriminators are distinct",
        account_discs.len() + ix_discs.len()
    );
}
